package io.github.diodeme.ji.relay;

import java.time.Instant;
import java.util.List;
import java.util.Optional;
import java.util.Set;

/** Relay-owned metadata only. Session, Permission, transcript, and Provider facts are forbidden here. */
public interface RelayMetadataStore extends AutoCloseable {
    Optional<Device> device(String tenantId, String deviceId);
    List<Device> devices(String tenantId);
    void saveDevice(Device device);
    void revokeDevice(String tenantId, String deviceId, Instant revokedAt);
    Optional<Host> host(String tenantId, String hostId);
    void saveHost(Host host);
    Optional<Invitation> invitation(String tenantId, String invitationId);
    void saveInvitation(Invitation invitation);
    boolean confirmInvitation(String tenantId, String invitationId, String confirmingDeviceId, Instant confirmedAt);
    boolean consumeInvitation(String tenantId, String invitationId, String deviceId, byte[] publicKey, Instant consumedAt);
    Optional<Grant> grant(String tenantId, String hostId, String deviceId);
    void saveGrant(Grant grant);

    @Override default void close() {}

    record Device(String tenantId, String deviceId, byte[] publicKey, Set<RelayRole> roles,
                  Instant createdAt, Optional<Instant> revokedAt) {
        public Device {
            tenantId = required(tenantId, "tenantId");
            deviceId = required(deviceId, "deviceId");
            if (publicKey == null || publicKey.length < 32) throw new IllegalArgumentException("invalid public key");
            publicKey = publicKey.clone();
            roles = Set.copyOf(roles);
            java.util.Objects.requireNonNull(createdAt, "createdAt");
            revokedAt = revokedAt == null ? Optional.empty() : revokedAt;
        }
        @Override public byte[] publicKey() { return publicKey.clone(); }
        public boolean active() { return revokedAt.isEmpty(); }
    }

    record Host(String tenantId, String hostId, byte[] publicKey, int protocolVersion,
                String releaseVersion, Instant registeredAt) {
        public Host {
            tenantId = required(tenantId, "tenantId");
            hostId = required(hostId, "hostId");
            if (publicKey == null || publicKey.length != 32) throw new IllegalArgumentException("invalid Host public key");
            publicKey = publicKey.clone();
            releaseVersion = required(releaseVersion, "releaseVersion");
            java.util.Objects.requireNonNull(registeredAt, "registeredAt");
        }
        @Override public byte[] publicKey() { return publicKey.clone(); }
    }

    record Invitation(String tenantId, String invitationId, String issuerDeviceId, Set<String> hostIds,
                      byte[] secretHash, String fingerprint, Instant expiresAt,
                      Optional<Instant> confirmedAt, Optional<Instant> consumedAt) {
        public Invitation {
            tenantId = required(tenantId, "tenantId");
            invitationId = required(invitationId, "invitationId");
            issuerDeviceId = required(issuerDeviceId, "issuerDeviceId");
            hostIds = Set.copyOf(hostIds);
            if (hostIds.isEmpty()) throw new IllegalArgumentException("invitation requires a Host selection");
            if (secretHash == null || secretHash.length != 32) throw new IllegalArgumentException("invalid invitation hash");
            secretHash = secretHash.clone();
            fingerprint = required(fingerprint, "fingerprint");
            java.util.Objects.requireNonNull(expiresAt, "expiresAt");
            confirmedAt = confirmedAt == null ? Optional.empty() : confirmedAt;
            consumedAt = consumedAt == null ? Optional.empty() : consumedAt;
        }
        @Override public byte[] secretHash() { return secretHash.clone(); }
    }

    record Grant(String tenantId, String hostId, String deviceId, Set<String> requestedScopes, Instant createdAt) {
        public Grant {
            tenantId = required(tenantId, "tenantId");
            hostId = required(hostId, "hostId");
            deviceId = required(deviceId, "deviceId");
            requestedScopes = Set.copyOf(requestedScopes);
            java.util.Objects.requireNonNull(createdAt, "createdAt");
        }
    }

    private static String required(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
        return value;
    }
}
